/**
 * Discord Node - Version 2
 * Discriminator: resource=member, operation=ban
 */


interface Credentials {
  discordBotApi: CredentialReference;
  discordOAuth2Api: CredentialReference;
  discordWebhookApi?: CredentialReference;
}

/** Ban a member from a server, optionally deleting their recent messages */
export type DiscordV2MemberBanParams = {
  resource: 'member';
  operation: 'ban';
  authentication?: 'botToken' | 'oAuth2' | 'webhook' | Expression<string>;
/**
 * Select the server (guild) that your bot is connected to
 * @searchListMethod guildSearch
 * @displayOptions.show { authentication: ["botToken", "oAuth2"] }
 * @default {"mode":"list","value":""}
 */
    guildId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Select the user you want to assign a role to
 * @searchListMethod userSearch
 * @displayOptions.hide { authentication: ["webhook"] }
 * @default {"mode":"list","value":""}
 */
    userId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * How much of the user's recent message history to delete on ban
 * @displayOptions.hide { authentication: ["webhook"] }
 * @default 0
 */
    deleteMessageSeconds?: 0 | 3600 | 21600 | 43200 | 86400 | 259200 | 604800 | Expression<number>;
/**
 * The reason recorded in the server audit log
 * @displayOptions.hide { authentication: ["webhook"] }
 * @default suspicious_spam
 */
    reason?: 'suspicious_spam' | 'compromised' | 'rule_break' | 'other' | Expression<string>;
/**
 * The custom reason recorded in the server audit log
 * @displayOptions.show { reason: ["other"] }
 * @displayOptions.hide { authentication: ["webhook"] }
 */
    reasonCustom?: string | Expression<string>;
};

export type DiscordV2MemberBanOutput = {
  success?: boolean;
};

export type DiscordV2MemberBanNode = {
  type: 'n8n-nodes-base.discord';
  version: 2;
  config: NodeConfig<DiscordV2MemberBanParams> & { credentials?: Credentials };
  output?: Items<DiscordV2MemberBanOutput>;
};